from typing import List

class Solution:
    def maxScore(self, n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
        dp = [stayScore[0][c] for c in range(n)]
        for i in range(1, k):
            ndp = [0] * n
            for c in range(n):
                best = dp[c] + stayScore[i][c]
                for p in range(n):
                    if p != c:
                        v = dp[p] + travelScore[p][c]
                        if v > best:
                            best = v
                ndp[c] = best
            dp = ndp
        return max(dp)
