import json
from hypothesis import strategies as st


@st.composite
def gen(draw):
    n = draw(st.integers(1, 3))
    k = draw(st.integers(1, 4))
    stay = [
        draw(st.lists(st.sampled_from([1, 2, 50, 99, 100]), min_size=n, max_size=n))
        for _ in range(k)
    ]
    raw = [
        draw(st.lists(st.sampled_from([0, 1, 50, 100]), min_size=n, max_size=n))
        for _ in range(n)
    ]
    travel = [[0 if i == j else raw[i][j] for j in range(n)] for i in range(n)]
    return (
        json.dumps(n) + "\n"
        + json.dumps(k) + "\n"
        + json.dumps(stay) + "\n"
        + json.dumps(travel)
    )


def validate(inp):
    lines = inp.split("\n")
    if len(lines) != 4:
        return False
    n = json.loads(lines[0])
    k = json.loads(lines[1])
    stay = json.loads(lines[2])
    travel = json.loads(lines[3])
    if not (isinstance(n, int) and isinstance(k, int)):
        return False
    if not (1 <= n <= 200 and 1 <= k <= 200):
        return False
    if len(stay) != k or any(len(r) != n for r in stay):
        return False
    if len(travel) != n or any(len(r) != n for r in travel):
        return False
    for r in stay:
        for v in r:
            if not (isinstance(v, int) and 1 <= v <= 100):
                return False
    for i in range(n):
        for j in range(n):
            v = travel[i][j]
            if not (isinstance(v, int) and 0 <= v <= 100):
                return False
        if travel[i][i] != 0:
            return False
    return True


def ref(inp):
    lines = inp.split("\n")
    n = json.loads(lines[0])
    k = json.loads(lines[1])
    stay = json.loads(lines[2])
    travel = json.loads(lines[3])

    # Brute force: on each day the tourist either stays in the current city
    # (earning stayScore[day][curr]) or moves to a different city dest
    # (earning travelScore[curr][dest]). Try every possibility from every start.
    def rec(day, curr):
        if day == k:
            return 0
        best = stay[day][curr] + rec(day + 1, curr)
        for dest in range(n):
            if dest != curr:
                best = max(best, travel[curr][dest] + rec(day + 1, dest))
        return best

    answer = max(rec(0, start) for start in range(n))
    return json.dumps(answer)
